import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const INSURANCE_TYPES = ['국민연금', '건강보험', '고용보험'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

@Controller('api/v1')
export class FnSfr02204Controller {
  @Post('/social-insurance-grades')
  @HttpCode(200)
  async createSocialInsuranceGrade(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '급여 담당자');
    const data = checks.inputOf(req.body);
    const employeeIdText = String(data['employeeId'] ?? '').trim();
    const insuranceType = textOf(data['insuranceType']);
    const afterGrade = textOf(data['afterGrade']);
    const applyStartMonth = textOf(data['applyStartMonth']);
    const reason = textOf(data['reason']);
    if (!employeeIdText || !insuranceType || !afterGrade || !applyStartMonth) {
      throw new ApiError(422, 'INVALID_GRADE_INPUT', '필수 항목(임직원, 보험 종류, 변경 후 등급, 적용 시작월)을 모두 입력해 주세요.');
    }
    const employeeIdNumber = Number(employeeIdText);
    if (!Number.isInteger(employeeIdNumber) || employeeIdNumber <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '임직원 값이 올바르지 않습니다.');
    }
    if (!INSURANCE_TYPES.includes(insuranceType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '보험 종류는 국민연금, 건강보험, 고용보험 중 하나여야 합니다.');
    }
    if (afterGrade.length > 20) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 후 등급은 20자 이하로 입력해 주세요.');
    }
    if (!/^\d{4}(0[1-9]|1[0-2])$/.test(applyStartMonth)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작월은 YYYYMM 형식으로 입력해 주세요.');
    }
    if (reason.length > 500) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 사유는 500자 이하로 입력해 주세요.');
    }
    // TODO: 적용 시작월 마감 여부 검사 (409 PAYROLL_MONTH_CLOSED) - 마감 테이블이 입력에 없어 구현하지 못함
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId: employeeIdNumber },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_GRADE_NOT_FOUND', '대상 임직원을 찾을 수 없습니다.');
      }
      // 가정: 해당 임직원·보험 종류의 최신 이력 행의 변경 후 등급이 변경 전 등급이다.
      const latest = await db.query(
        'SELECT after_grade AS "afterGrade" FROM social_insurance_grade WHERE employee_id = CAST(:employeeId AS bigint) AND insurance_type = :insuranceType ORDER BY changed_at DESC, social_insurance_grade_id DESC LIMIT 1',
        { employeeId: employeeIdNumber, insuranceType },
      );
      if (latest.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_GRADE_NOT_FOUND', '대상 임직원의 등급이 등록되어 있지 않습니다.');
      }
      const rows = await db.query(
        'INSERT INTO social_insurance_grade (employee_id, insurance_type, before_grade, after_grade, apply_start_month, reason, changed_at, changed_by, created_at, updated_at) VALUES (CAST(:employeeId AS bigint), :insuranceType, :beforeGrade, :afterGrade, :applyStartMonth, :reason, now(), CAST(:userId AS bigint), now(), now()) RETURNING social_insurance_grade_id AS "socialInsuranceGradeId", before_grade AS "beforeGrade", after_grade AS "afterGrade", apply_start_month AS "applyStartMonth"',
        {
          employeeId: employeeIdNumber,
          insuranceType,
          beforeGrade: latest[0]['afterGrade'],
          afterGrade,
          applyStartMonth,
          reason: reason === '' ? null : reason,
          userId: user.id,
        },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-grades')
  async listSocialInsuranceGrades(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '급여 담당자');
    const query = checks.queryOf(req.query);
    const employeeIdText = String(query['employeeId'] ?? '').trim();
    const insuranceType = textOf(query['insuranceType']);
    let employeeId: number | null = null;
    if (employeeIdText) {
      employeeId = Number(employeeIdText);
      if (!Number.isInteger(employeeId) || employeeId <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 값이 올바르지 않습니다.');
      }
    }
    if (insuranceType && !INSURANCE_TYPES.includes(insuranceType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '보험 종류 값이 올바르지 않습니다.');
    }
    const pageText = String(query['page'] ?? '').trim();
    const sizeText = String(query['size'] ?? '').trim();
    const page = pageText ? Number(pageText) : 0;
    const size = sizeText ? Number(sizeText) : DEFAULT_SIZE;
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const params = {
      employeeId,
      insuranceType: insuranceType === '' ? null : insuranceType,
    };
    const where = 'WHERE (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint)) AND (CAST(:insuranceType AS varchar) IS NULL OR insurance_type = CAST(:insuranceType AS varchar))';
    return transaction(async (db) => {
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM social_insurance_grade ' + where,
        params,
      );
      const items = await db.query(
        'SELECT social_insurance_grade_id AS "socialInsuranceGradeId", employee_id AS "employeeId", insurance_type AS "insuranceType", before_grade AS "beforeGrade", after_grade AS "afterGrade", apply_start_month AS "applyStartMonth", reason AS "reason", changed_at AS "changedAt", changed_by AS "changedBy" FROM social_insurance_grade ' + where + ' ORDER BY changed_at DESC, social_insurance_grade_id DESC LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, limit, offset: page * limit },
      );
      return { items, page, size: limit, total: Number(counts[0]['total']) };
    });
  }
}

