import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPES: [string, string][] = [
  ['국민연금', '국민연금'],
  ['건강보험', '건강보험'],
  ['고용보험', '고용보험'],
];
const SIZE = 20;

export default function FnSfr02204Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [insuranceType, setInsuranceType] = useState('');
  const [applied, setApplied] = useState<Row>({ employeeId: '', insuranceType: '' });
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);

  const [formEmployeeId, setFormEmployeeId] = useState<number | string>('');
  const [formType, setFormType] = useState('');
  const [afterGrade, setAfterGrade] = useState('');
  const [applyStartMonth, setApplyStartMonth] = useState('');
  const [reason, setReason] = useState('');

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/social-insurance-grades', role, undefined, {
        employeeId: applied.employeeId,
        insuranceType: applied.insuranceType,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );

  function search() {
    setPage(0);
    setApplied({ employeeId, insuranceType });
  }

  function reset() {
    setEmployeeId('');
    setInsuranceType('');
    setPage(0);
    setApplied({ employeeId: '', insuranceType: '' });
  }

  function openCreate() {
    setFormEmployeeId('');
    setFormType('');
    setAfterGrade('');
    setApplyStartMonth('');
    setReason('');
    setCreating(true);
  }

  async function submit() {
    if (formEmployeeId === '' || !formType || !afterGrade.trim() || !applyStartMonth.trim()) {
      throw new Error('임직원, 보험 종류, 변경 후 등급, 적용 시작월을 모두 입력해 주세요.');
    }
    if (!/^\d{4}(0[1-9]|1[0-2])$/.test(applyStartMonth.trim())) {
      throw new Error('적용 시작월은 YYYYMM 형식(예: 202607)으로 입력해 주세요.');
    }
    await call('POST', '/social-insurance-grades', role, {
      employeeId: formEmployeeId,
      insuranceType: formType,
      afterGrade: afterGrade.trim(),
      applyStartMonth: applyStartMonth.trim(),
      reason: reason.trim(),
    });
    notify('사회보험 등급을 변경했습니다.');
    setCreating(false);
    setPage(0);
    list.reload();
  }

  const data = list.data;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>변경 이력 건수</h2>
        <strong><Num value={data ? data.total : 0} /></strong>
      </section>
      <section className="box span-12">
        <h2>등급 변경 이력</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
          <Field label="보험 종류">
            <Select value={insuranceType} onChange={setInsuranceType} options={TYPES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>등급 변경</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={data ? data.items : []}
          empty="등급 변경 이력이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'insuranceType', label: '보험 종류', render: (r) => <Badge value={r.insuranceType} /> },
            { key: 'beforeGrade', label: '변경 전 등급' },
            { key: 'afterGrade', label: '변경 후 등급' },
            { key: 'applyStartMonth', label: '적용 시작월' },
            { key: 'changedAt', label: '변경 일시', render: (r) => <DateText value={r.changedAt} time /> },
            { key: 'changedBy', label: '변경자', render: (r) => <RefName table="employee" role={role} value={r.changedBy} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {detail ? (
        <Drawer title="등급 변경 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['임직원', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['보험 종류', <Badge value={detail.insuranceType} />],
              ['변경 전 등급', String(detail.beforeGrade ?? '')],
              ['변경 후 등급', String(detail.afterGrade ?? '')],
              ['적용 시작월', String(detail.applyStartMonth ?? '')],
              ['변경 사유', String(detail.reason ?? '')],
              ['변경 일시', <DateText value={detail.changedAt} time />],
              ['변경자', <RefName table="employee" role={role} value={detail.changedBy} />],
            ]}
          />
        </Drawer>
      ) : null}
      {creating ? (
        <Drawer title="사회보험 등급 변경" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="변경">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={formEmployeeId} onChange={setFormEmployeeId} />
            </Field>
            <Field label="보험 종류" required>
              <Select value={formType} onChange={setFormType} options={TYPES} />
            </Field>
            <Field label="변경 후 등급" required>
              <TextInput value={afterGrade} onChange={setAfterGrade} />
            </Field>
            <Field label="적용 시작월" required hint="YYYYMM 형식">
              <TextInput value={applyStartMonth} onChange={setApplyStartMonth} placeholder="202607" />
            </Field>
            <Field label="변경 사유" wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
